    // Helper method to compare strings ignoring diacritics
    private bool ContainsVietnamese(string source, string search)
    {
        if (string.IsNullOrEmpty(source) || string.IsNullOrEmpty(search))
            return false;

        // Remove diacritics from both strings
        string normalizedSource = RemoveDiacritics(source.ToLower());
        string normalizedSearch = RemoveDiacritics(search.ToLower());

        return normalizedSource.Contains(normalizedSearch);
    }

    // Helper method to remove diacritics from a string
    private string RemoveDiacritics(string text)
    {
        var normalizedString = text.Normalize(NormalizationForm.FormD);
        var stringBuilder = new System.Text.StringBuilder();

        foreach (var c in normalizedString)
        {
            var unicodeCategory = CharUnicodeInfo.GetUnicodeCategory(c);
            if (unicodeCategory != UnicodeCategory.NonSpacingMark)
            {
                stringBuilder.Append(c);
            }
        }

        return stringBuilder.ToString().Normalize(NormalizationForm.FormC);
    }

